-- Mod-authored natural wonder portrait descriptions, de_DE overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "Keine Beschreibung für dieses Naturwunder."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Ein riesiger Einschlagkrater, von seinem Rand aus gesehen, eine zerklüftete Schale, die in den blassen Wüstenboden geschlagen ist. Der nahe Hang ist von grünem Buschwerk bedeckt, das in die schattige Grube abfällt, deren Grund in tiefer brauner Dunkelheit liegt, und der ferne Rand erhebt sich in Bändern aus Sandbraun und Gold unter einem dunstigen Himmel."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Eine Stufenpyramide aus massivem Gold, deren steile Treppe an ihrer Vorderseite zu einem kleinen Schrein an der Spitze hinaufführt. Riesige Goldbarren sind an ihrem Fuß zwischen schlanken dunklen Bäumen gestapelt, und die ganze Szene leuchtet gelb, der Schatz der sagenhaften Stadt buchstäblich gemacht. Die Lichtstrahlen dahinter wirken wie ein Sonnenaufgang, der über der verlorenen Stadt anbricht."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Eine Quelle unmöglich hellen türkisfarbenen Wassers quillt aus einem Becken auf dunklen Felsklippen empor und stürzt als leuchtender Wasserfall in den Teich darunter. Büschel grünen Grases klammern sich an den schwarzen Fels, Palmwedel rahmen einen warmen goldenen Himmel, und winzige Funken im Wasser kennzeichnen es als magisch statt natürlich."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Ein perfekter Vulkankegel füllt das Bild, seine breite Schneehaube reicht über den größten Teil der Hänge hinab. Der Schnee ist in sanftem Weiß und blassem Blau gegen einen tiefblauen Himmel gemalt, und ein Streifen aus grünem Buschwerk und nebligem Wasser liegt am Fuß des Berges."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Ein Geysir bricht aus einem zerklüfteten blassen Hügel hervor, seine weiße Gischt fächert sich aus und füllt den ganzen Himmel mit Dunst gegen das Blau. Dunkler immergrüner Wald drängt sich zu beiden Seiten heran, und der Vordergrund ist eine Kruste aus Mineralterrassen in Sandbraun, Ocker und Braun."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Ein großes Kalksteinvorgebirge erhebt sich aus einem flachen Meer, steile blasse Klippen an seiner linken Seite und ein langer Hang dunkelgrüner Vegetation, der an seinem Rücken hinabläuft. Die ganze Szene ist in Gold getaucht, Himmel und Wasser leuchten wie am späten Nachmittag."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Eine riesige schneegestreifte Kuppel füllt in eisigem Weiß und Blau die obere Bildhälfte, ein Kranz kleiner Wolken treibt an ihrem Fuß. Darunter breitet sich grüne Savanne aus, wo zwei Giraffen an einem blassen Wasserloch stehen, flachkronige Bäume an den Rändern der Szene."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Ein breiter türkisfarbener See reicht zurück bis zu blassen Hügeln am Horizont, eingefasst von felsigen sandbraunen Vorsprüngen zu beiden Seiten. In der Mitte des Vordergrunds taucht ein Flusspferd auf, sein Kopf und Rücken durchbrechen das gekräuselte Wasser, unter einem weißen Lichtschein, der den Himmel füllt."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Ein flach gekappter Tafelberg aus geschichtetem rotorangem Gestein erhebt sich allein aus einer trockenen Ebene, gebänderte Felswände über langen Hängen abgestürzten Gesteins. Spärliches grünes Buschwerk sprenkelt den sandigen Boden an seinem Fuß, und der flache Gipfel zeichnet eine harte Linie gegen einen hellblauen Himmel."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Eine Pyramide aus gebändertem Fels und Schnee erhebt sich gegen einen tiefblauen Himmel, ihre gestreifte Seite auf einer Flanke warm golden beleuchtet. Darunter ist der Vordergrund ganz raues Schneefeld und Eisgrate in kaltem blauem Schatten."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Eine Gruppe zerklüfteter Wüstengipfel aus orangebraunem Sandstein, tiefe Rinnen durchfurchen ihre Flanken, mit einem sanften Lichtschein, der hinter dem mittleren Gipfel hervorbricht. Verstreute Felsblöcke übersäen die sandige Fläche im Vordergrund unter einem klaren blauen Himmel."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Ein kahler rotbrauner Berg, dessen untere Hänge unter Haufen grauer Felsblöcke begraben sind, die mit Silbererz glitzern. Ein Pfad windet sich seine Flanke hinauf, Reihen dunkler quadratischer Blöcke säumen seinen Fuß wie Grubenbauten, und der staubige Gipfel steht gegen einen blauen Himmel."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Eine Unterwasserszene: Korallen drängen sich in Orange, Rot, Violett und blassem Blau an den linken und unteren Rand des Bildes, mit Röhrenschwämmen, die aufrecht zwischen den Ästen stehen. Kleine tropische Fische treiben durch das tiefblaue Wasser, ein leuchtend gelber in der Mitte. Das Licht verblasst zur oberen rechten Seite hin in offene Dunkelheit."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Ein monumentales Torhaus, das für die legendären Minen steht: eine hohe dunkle Festungsmauer, gekrönt von goldbespitzten Zinnen, mit einer Tür in ihrer Mitte, flankiert von sandbraunen Steintürmen. Davor ist der blasse Felsboden in geschwungene Kurven gehauen, als wäre der Boden selbst glatt aus dem Stein gebrochen worden."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Ein üppig grüner Berg erhebt sich zu einem gerundeten Gipfel, Dschungel bedeckt seine Hänge, außer wo orangebrauner Fels in Klippen durchbricht. Hohe Grashalme mit kleinen blauen Blüten füllen den Vordergrund, und der Himmel dahinter ist ein leuchtendes tropisches Türkis."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Ein großer roter Monolith liegt quer in der mittleren Distanz, seine gerundete Sandsteinmasse mit senkrechten Rillen durchfurcht und im Licht orange leuchtend. Davor erstreckt sich flaches Outback-Buschland, rote Erde durchsetzt mit niedrigem grünem Gestrüpp und Grasbüscheln, unter einem hellblauen Himmel."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Ein dunkler Vulkankegel erhebt sich aus dem Meer jenseits eines Streifens blass türkisfarbenen Wassers, gesehen von einem Dschungelufer aus, dessen breite grüne Blätter die Szene rahmen. Der Himmel darüber brennt schwefelgelb, mit einem schwachen Rauchkringel über dem Gipfel, der auf den bevorstehenden Ausbruch hindeutet."
